import { Settings as SettingsIcon } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

export const Settings = () => {
  const { user, logout } = useAuth();

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-gray-900">Account Settings</h2>
        <p className="text-sm text-gray-500">Manage your profile, preferences, and security.</p>
      </div>

      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex items-center gap-4">
          <div className="w-16 h-16 rounded-full bg-farmGreen text-white flex items-center justify-center text-2xl font-bold">
            {user?.name?.charAt(0) || 'U'}
          </div>
          <div>
            <h3 className="text-xl font-bold text-gray-900">{user?.name}</h3>
            <p className="text-gray-500 "><span className="font-semibold capitalize">{user?.role}</span> Account • {user?.email}</p>
          </div>
        </div>
        
        <div className="p-6 bg-gray-50">
          <h4 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
            <SettingsIcon size={18} /> Application Preferences
          </h4>
          <p className="text-sm text-gray-500 mb-6">Profile updates and notification settings are managed here.</p>
          
          <button 
            onClick={logout}
            className="px-6 py-2.5 bg-red-50 text-red-600 hover:bg-red-100 font-bold rounded-lg transition-colors border border-red-200"
          >
            Sign Out
          </button>
        </div>
      </div>
    </div>
  );
};
